/* ============================================
   NOTIFICATION CENTER COMPONENT
   The persistent inbox: header with unread
   count and mark-all-read, filter tabs with
   counts, and a scrollable list of items.

   Toast interrupts; this accumulates. The
   container is a floating panel, so it works
   dropped from a bell icon or inline on a page.
   ============================================ */

.ds-notification-center {
  display: flex;
  flex-direction: column;
  width: 100%;
  background-color: var(--color-bg-container-primary);
  border: var(--border-025) solid var(--color-bg-container-border);
  border-radius: var(--radius-300);
  overflow: hidden;
}

/* ============================================
   HEADER
   ============================================ */

.ds-notification-center__header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--gap-200);
  padding: var(--padding-300) var(--padding-300) var(--padding-150);
}

.ds-notification-center__heading {
  display: flex;
  align-items: baseline;
  gap: var(--gap-100);
  min-width: 0;
}

.ds-notification-center__title {
  color: var(--color-text-primary);
  font-family: var(--font-title-body-family);
  font-size: var(--font-title-body-size);
  font-weight: var(--font-title-body-weight);
  line-height: var(--font-title-body-line-height);
  letter-spacing: var(--font-title-body-letter-spacing);
  white-space: nowrap;
}

.ds-notification-center__unread {
  color: var(--color-text-tertiary);
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  white-space: nowrap;
}

.ds-notification-center__mark-all {
  flex: none;
  padding: 0;
  background: none;
  border: none;
  cursor: pointer;
  color: var(--color-action-primary-text-tertiary);
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-size: var(--font-paragraph-sm-emphasis-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  letter-spacing: var(--font-paragraph-sm-emphasis-letter-spacing);
  transition: color var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-notification-center__mark-all:hover {
  color: var(--color-action-primary-text-secondary);
}

.ds-notification-center__mark-all:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
  border-radius: var(--radius-050);
}

/* ============================================
   FILTER TABS
   ============================================ */

.ds-notification-center__tabs {
  display: flex;
  gap: var(--gap-050);
  padding: 0 var(--padding-300) var(--padding-150);
  border-bottom: var(--border-025) solid var(--color-divider);
}

.ds-notification-center__tab {
  display: inline-flex;
  align-items: center;
  gap: var(--gap-050);
  padding: var(--padding-100) var(--padding-200);
  background: none;
  border: none;
  border-radius: var(--radius-pill);
  cursor: pointer;
  color: var(--color-text-secondary);
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-size: var(--font-paragraph-sm-emphasis-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  letter-spacing: var(--font-paragraph-sm-emphasis-letter-spacing);
  transition:
    background-color var(--motion-duration-fast) var(--motion-ease-standard),
    color var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-notification-center__tab:hover {
  background-color: var(--color-action-passive-bg-hover);
  color: var(--color-text-primary);
}

.ds-notification-center__tab:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: -2px;
}

.ds-notification-center__tab--active {
  background-color: var(--color-bg-container-tertiary);
  color: var(--color-text-primary);
}

.ds-notification-center__tab-count {
  color: var(--color-text-tertiary);
  font-variant-numeric: tabular-nums;
}

/* ============================================
   LIST
   ============================================ */

.ds-notification-center__list {
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  padding: var(--padding-100) 0;
}

.ds-notification-center__list > .ds-notification-item:not(:last-child) {
  border-bottom: var(--border-025) solid var(--color-divider);
}

/* Give the built-in empty state breathing room */
.ds-notification-center__list > .ds-empty-state {
  padding: var(--padding-500) var(--padding-300);
}

/* ============================================
   NOTIFICATION ITEM
   ============================================ */

.ds-notification-item {
  display: flex;
  align-items: flex-start;
  gap: var(--gap-200);
  padding: var(--padding-200) var(--padding-300);
}

/* The slot is a fixed column as wide as its largest medium — an sm Avatar
   (32px, the --icon-size-800 rung) — with smaller media centred in it, so
   every row's text starts on the same edge whether its medium is an avatar
   or a bare icon. */
.ds-notification-item__media {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  width: var(--icon-size-800);
  color: var(--color-icon-primary);
}

.ds-notification-item__media .material-symbols-rounded {
  --icon-size: var(--icon-size-600);
}

.ds-notification-item__body {
  display: flex;
  flex-direction: column;
  gap: var(--gap-050);
  min-width: 0;
  flex: 1 1 auto;
}

.ds-notification-item__top {
  display: flex;
  align-items: center;
  gap: var(--gap-100);
}

.ds-notification-item__title {
  flex: 1 1 auto;
  min-width: 0;
  color: var(--color-text-primary);
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
}

.ds-notification-item--unread .ds-notification-item__title {
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  letter-spacing: var(--font-paragraph-sm-emphasis-letter-spacing);
}

.ds-notification-item__time {
  flex: none;
  color: var(--color-text-tertiary);
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  white-space: nowrap;
}

/* Unread dot — informational, so it takes the info status colour rather
   than the action teal, at the full-strength border weight for the same
   reason Meter's fill does: a tint vanishes in a small mark. 8px because
   a 4px dot is sub-perceptual at reading distance — the dot is the row's
   one unmistakable unread signal, so it has to register at a glance. */
.ds-notification-item__dot {
  flex: none;
  width: var(--gap-200);
  height: var(--gap-200);
  border-radius: var(--radius-pill);
  background-color: var(--color-status-info-border);
}

.ds-notification-item__text {
  color: var(--color-text-secondary);
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
}

.ds-notification-item__actions {
  display: flex;
  align-items: center;
  gap: var(--gap-200);
  padding-top: var(--padding-050);
}

/* ============================================
   SCREEN READER TEXT
   ============================================ */

.ds-notification-item__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* Icons take the colour of the text around them. Explicit, not just
   inherited by default: a consumer stylesheet that sets a colour on
   .material-symbols-rounded itself (a common global default) would
   otherwise override inheritance and detach the icon from the state
   colours this component sets on its parents. */
.ds-notification-center .material-symbols-rounded {
  color: inherit;
}

'use client';

import React, { useId, useState } from 'react';
import { EmptyState } from '../EmptyState/EmptyState';
import './NotificationCenter.css';
import '../../fonts/material-symbols.css';

export interface NotificationCenterTab {
  /** Display label */
  label: string;
  /** Unique tab identifier */
  value: string;
  /** Count shown beside the label, e.g. the number of notifications in this filter. */
  count?: number;
}

/** Props owned by NotificationItem itself — everything else falls through to the root element. */
type NotificationItemOwnProps = {
  /** One-line headline, e.g. who did what. */
  title: string;
  /** When it happened, as already-formatted text like "2m" or "Mon". */
  time?: string;
  /** Marks the notification as not yet read: a dot beside the time and emphasised title. */
  unread?: boolean;
  /** Leading visual — a Material Symbol name (string) or a custom element (e.g. an Avatar). */
  media?: string | React.ReactNode;
  /** Action row under the body — typically compact Buttons like "Reply" or "Retry". */
  actions?: React.ReactNode;
  /** Additional CSS classes */
  className?: string;
  /** Supporting copy under the title. */
  children?: React.ReactNode;
};

export interface NotificationItemProps
  extends NotificationItemOwnProps,
    Omit<React.ComponentPropsWithoutRef<'article'>, keyof NotificationItemOwnProps> {}

/**
 * NotificationItem is one row of a NotificationCenter: a leading visual, a
 * headline with its time, supporting copy, and an optional row of actions.
 * An unread item takes a dot and an emphasised title.
 */
export const NotificationItem = React.forwardRef<HTMLElement, NotificationItemProps>(
  ({ title, time, unread = false, media, actions, className = '', children, ...rest }, ref) => {
    const baseClass = 'ds-notification-item';

    const classes = [baseClass, unread ? `${baseClass}--unread` : '', className]
      .filter(Boolean)
      .join(' ');

    return (
      <article {...rest} ref={ref} className={classes}>
        {media && (
          <span className={`${baseClass}__media`} aria-hidden="true">
            {typeof media === 'string' ? (
              <span className="material-symbols-rounded">{media}</span>
            ) : (
              media
            )}
          </span>
        )}
        <div className={`${baseClass}__body`}>
          <div className={`${baseClass}__top`}>
            <span className={`${baseClass}__title`}>{title}</span>
            {time && <span className={`${baseClass}__time`}>{time}</span>}
            {unread && (
              <span className={`${baseClass}__dot`}>
                <span className={`${baseClass}__sr`}>Unread</span>
              </span>
            )}
          </div>
          {children && <div className={`${baseClass}__text`}>{children}</div>}
          {actions && <div className={`${baseClass}__actions`}>{actions}</div>}
        </div>
      </article>
    );
  },
);

NotificationItem.displayName = 'NotificationItem';

/** Props owned by NotificationCenter itself — everything else falls through to the root element. */
type NotificationCenterOwnProps = {
  /** Heading shown in the header. */
  title?: string;
  /** How many notifications are unread, shown under the heading. Omit to hide the line. */
  unreadCount?: number;
  /** Fires when "Mark all read" is pressed; the control only renders when this is set. */
  onMarkAllRead?: () => void;
  /** Text of the mark-all-read control. */
  markAllLabel?: string;
  /** Filter tabs under the header, each with an optional count. */
  tabs?: NotificationCenterTab[];
  /** Active tab value for controlled use. Pair with `onTabChange`. */
  activeTab?: string;
  /** Initially active tab value for uncontrolled use. Defaults to the first tab. */
  defaultTab?: string;
  /** Fires with the newly selected tab's value. */
  onTabChange?: (value: string) => void;
  /** What to render when there are no children — defaults to a built-in empty state. */
  emptyState?: React.ReactNode;
  /** Additional CSS classes */
  className?: string;
  /** The notifications, newest first — typically NotificationItems. */
  children?: React.ReactNode;
};

export interface NotificationCenterProps
  extends NotificationCenterOwnProps,
    Omit<React.ComponentPropsWithoutRef<'section'>, keyof NotificationCenterOwnProps> {}

/**
 * NotificationCenter is the persistent inbox for everything that happened
 * while the user was away: a header with the unread count and a mark-all-read
 * control, optional filter tabs with counts, and a scrollable list of
 * NotificationItems. Filtering is the consumer's job — swap the children when
 * the tab changes.
 *
 * Toast interrupts; this accumulates.
 */
export const NotificationCenter = React.forwardRef<HTMLElement, NotificationCenterProps>(
  (
    {
      title = 'Notifications',
      unreadCount,
      onMarkAllRead,
      markAllLabel = 'Mark all read',
      tabs,
      activeTab,
      defaultTab,
      onTabChange,
      emptyState,
      className = '',
      children,
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-notification-center';

    const isTabControlled = activeTab !== undefined;
    const [uncontrolledTab, setUncontrolledTab] = useState(defaultTab ?? tabs?.[0]?.value);
    const currentTab = isTabControlled ? activeTab : uncontrolledTab;

    // Ids tying each tab to the list as its tabpanel. Index-based, because
    // tab values are consumer strings and not guaranteed id-safe.
    const idBase = useId();
    const panelId = `${idBase}-panel`;
    const tabIdFor = (index: number) => `${idBase}-tab-${index}`;
    const activeTabIndex = tabs?.findIndex((tab) => tab.value === currentTab) ?? -1;
    const hasTabs = !!tabs && tabs.length > 0;

    const selectTab = (value: string) => {
      if (!isTabControlled) setUncontrolledTab(value);
      onTabChange?.(value);
    };

    const handleTabKeyDown = (e: React.KeyboardEvent, index: number) => {
      if (!tabs) return;
      let target: NotificationCenterTab | undefined;
      switch (e.key) {
        case 'ArrowRight':
          e.preventDefault();
          target = tabs[(index + 1) % tabs.length];
          break;
        case 'ArrowLeft':
          e.preventDefault();
          target = tabs[(index - 1 + tabs.length) % tabs.length];
          break;
        case 'Home':
          e.preventDefault();
          target = tabs[0];
          break;
        case 'End':
          e.preventDefault();
          target = tabs[tabs.length - 1];
          break;
      }
      if (target) {
        selectTab(target.value);
        const tabList = (e.target as HTMLElement).parentElement;
        const buttons = tabList?.querySelectorAll<HTMLButtonElement>(`.${baseClass}__tab`);
        buttons?.[tabs.indexOf(target)]?.focus();
      }
    };

    const hasItems = React.Children.count(children) > 0;

    const classes = [baseClass, className].filter(Boolean).join(' ');

    return (
      <section {...rest} ref={ref} className={classes}>
        <header className={`${baseClass}__header`}>
          <div className={`${baseClass}__heading`}>
            <span className={`${baseClass}__title`}>{title}</span>
            {unreadCount !== undefined && unreadCount > 0 && (
              <span className={`${baseClass}__unread`} aria-live="polite">
                {unreadCount} unread
              </span>
            )}
          </div>
          {onMarkAllRead && (
            <button type="button" className={`${baseClass}__mark-all`} onClick={onMarkAllRead}>
              {markAllLabel}
            </button>
          )}
        </header>

        {hasTabs && (
          <div className={`${baseClass}__tabs`} role="tablist" aria-label={`${title} filters`}>
            {tabs.map((tab, index) => {
              const isActive = tab.value === currentTab;
              return (
                <button
                  key={tab.value}
                  type="button"
                  id={tabIdFor(index)}
                  role="tab"
                  aria-selected={isActive}
                  aria-controls={panelId}
                  tabIndex={isActive ? 0 : -1}
                  className={[
                    `${baseClass}__tab`,
                    isActive ? `${baseClass}__tab--active` : '',
                  ]
                    .filter(Boolean)
                    .join(' ')}
                  onClick={() => selectTab(tab.value)}
                  onKeyDown={(e) => handleTabKeyDown(e, index)}
                >
                  {tab.label}
                  {tab.count !== undefined && (
                    <span className={`${baseClass}__tab-count`}>{tab.count}</span>
                  )}
                </button>
              );
            })}
          </div>
        )}

        {/* The list is the panel the tabs control — tabpanel only when tabs exist. */}
        <div
          className={`${baseClass}__list`}
          role={hasTabs ? 'tabpanel' : undefined}
          id={hasTabs ? panelId : undefined}
          aria-labelledby={hasTabs && activeTabIndex >= 0 ? tabIdFor(activeTabIndex) : undefined}
        >
          {hasItems
            ? children
            : emptyState ?? (
                <EmptyState
                  icon="notifications"
                  title="Nothing new"
                  description="Notifications will collect here as they arrive."
                  size="compact"
                />
              )}
        </div>
      </section>
    );
  },
);

NotificationCenter.displayName = 'NotificationCenter';
